(() => {
'use strict';
const $=id=>document.getElementById(id),number=x=>Number.isFinite(x)?x.toLocaleString(undefined,{maximumFractionDigits:9}):'Pending',precision=x=>Number.isFinite(x)?x.toFixed(6):'Pending';
fetch('insta360_recovery_results.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Recovery snapshot not published yet');return r.json();}).then(report=>{
 const scales=['1x','4x'],rows=report.scales;
 $('insta-recovery-state').textContent=`Saved recovery snapshot ${new Date(report.updated).toLocaleString()} · queue ${report.queue.state||'prepared'}.`;
 const metrics=[['Source photographs preserved',d=>number(d.input_images)],['Retained cameras',d=>number(d.usable_images)],['Excluded cameras',d=>number(d.excluded_images)],['Supported sparse points',d=>number(d.metrics.points3D)],['Mean reprojection error, input px',d=>precision(d.metrics.mean_reprojection_error)],['Full-resolution-equivalent error, px',d=>precision(d.metrics.mean_reprojection_error*(d===rows['4x']?4:1))],['Mean track length',d=>precision(d.metrics.mean_track_length)],['Valid positive MVS depth ranges',d=>`${number(d.mvs_validation.references-d.mvs_validation.invalid_bounds.length)} / ${number(d.mvs_validation.references)}`],['Dense fused points',d=>number(d.dense?.vertex)],['Mesh vertices / faces',d=>`${number(d.mesh?.vertex)} / ${number(d.mesh?.face)}`]];
 $('insta-recovery-table').innerHTML=metrics.map(([label,get])=>`<tr><th scope="row">${label}</th>${scales.map(s=>`<td>${get(rows[s])}</td>`).join('')}</tr>`).join('');
 const stages=[['undistortion','Calibrated undistortion','CPU'],['depth_maps','Geometric depth / normals','CUDA'],['fusion','Dense fusion','CPU'],['mesh','Poisson mesh','CPU']];
 $('insta-recovery-times').innerHTML=stages.map(([key,label,device])=>`<tr><th scope="row">${label}</th><td>${device}</td>${scales.map(s=>{const stage=rows[s].stages[key];return `<td>${stage?.state==='complete'?(Number.isFinite(stage.seconds)?String(stage.seconds):'Complete · timer unavailable'):stage?.state||'Pending'}</td>`;}).join('')}</tr>`).join('');
 for(const [title,get] of [['Supported sparse points',d=>d.metrics.points3D],['Retained cameras',d=>d.usable_images],['Dense fused points',d=>d.dense?.vertex],['Full-resolution-equivalent reprojection error, px',d=>d.metrics.mean_reprojection_error*(d===rows['4x']?4:1)]]){
  const figure=document.createElement('figure');figure.className='count-chart-panel';const cap=document.createElement('figcaption');cap.textContent=title;figure.append(cap);
  const values=scales.map(s=>({x:parseInt(s,10),y:get(rows[s])}));
  if(values.some(v=>!Number.isFinite(v.y))){const p=document.createElement('p');p.textContent='Waiting for completed measurements at both resolutions.';figure.append(p);}
  else {const max=Math.max(...values.map(v=>v.y),.000001)*1.15,x=v=>75+(v-1)/3*450,y=v=>265-v/max*210;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 640 340');svg.classList.add('count-line-chart');svg.setAttribute('role','img');svg.setAttribute('aria-label',`${title}: native ${values[0].y}; 4x downsample ${values[1].y}`);svg.innerHTML=`${[0,.5,1].map(t=>`<line x1="75" y1="${y(max*t)}" x2="540" y2="${y(max*t)}" stroke="#ddd"/><text x="65" y="${y(max*t)+5}" text-anchor="end">${(max*t).toLocaleString(undefined,{maximumSignificantDigits:3})}</text>`).join('')}<line x1="75" y1="265" x2="540" y2="265" stroke="#222"/><polyline points="${values.map(v=>`${x(v.x)},${y(v.y)}`).join(' ')}" fill="none" stroke="#222" stroke-width="2"/>${values.map(v=>`<circle cx="${x(v.x)}" cy="${y(v.y)}" r="5" fill="#222"/><text x="${x(v.x)}" y="290" text-anchor="middle">${v.x}×</text>`).join('')}<text x="300" y="325" text-anchor="middle">Downsample factor</text>`;figure.append(svg);const p=document.createElement('p');p.className='chart-values';p.textContent=values.map(v=>`${v.x}×: ${number(v.y)}`).join(' · ');figure.append(p);}
  $('insta-recovery-charts').append(figure);
 }
}).catch(e=>{const status=$('insta-recovery-state');if(status)status.textContent=e.message;});
})();
